// ── The Complete 18-Byte Header Parser (Env, Weight, & Alive) ──

const gatewayId = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const TARGET_CLOUD_SID = 16777216; 

let incoming = "";
if (Buffer.isBuffer(msg.payload)) incoming = msg.payload.toString('hex');
else if (msg.payload && typeof msg.payload.hex === 'string') incoming = msg.payload.hex;
else if (typeof msg.payload === 'string') incoming = msg.payload;
else return null;

let buf = (context.get('buf') || '') + incoming.replace(/\s+/g, '');
const out = [];

// 1. GARBAGE COLLECTOR
if (buf.length > 8192) {
    buf = ""; 
    context.set('buf', buf);
    node.warn("Buffer overflow prevented. Flushed garbage data.");
    return null;
}

// 2. OMNI-SIGNATURE SCANNER
while (buf.length > 0) {
    // Look for all three known packet types
    let sensorIdx = buf.indexOf("013a"); // Type 0x01 (Env), Length 58
    let weightIdx = buf.indexOf("026a"); // Type 0x02 (Weight), Length 106
    let aliveIdx  = buf.indexOf("040c"); // Type 0x04 (Alive), Length 12

    let startIndex = -1;
    let packetType = 0;

    // Find whichever valid signature appears first in the current chunk
    const indices = [
        { type: 1, idx: sensorIdx },
        { type: 2, idx: weightIdx },
        { type: 4, idx: aliveIdx }
    ].filter(obj => obj.idx !== -1);

    if (indices.length > 0) {
        const earliest = indices.reduce((prev, curr) => prev.idx < curr.idx ? prev : curr);
        startIndex = earliest.idx;
        packetType = earliest.type;
    }

    if (startIndex === -1) {
        if (buf.length > 50) buf = buf.slice(-50);
        break; 
    }

    // 3. EXTRACT THE 18-BYTE PACKET MODE HEADER
    if (startIndex < 36) {
        buf = buf.slice(startIndex + 2); 
        continue;
    }

    const headerHex = buf.slice(startIndex - 36, startIndex); 

    // ── THE BIG-ENDIAN FIX ──
    const trueUidHex = headerHex.slice(10, 18);
    let dynamicUid = 0; 
    if (/^[0-9a-fA-F]{8}$/.test(trueUidHex)) {
        dynamicUid = Buffer.from(trueUidHex, 'hex').readUInt32BE(0); 
    } else {
        buf = buf.slice(startIndex + 2);
        continue;
    }

    // ── EXTRACT METADATA ──
    const trueRssiHex = headerHex.slice(18, 20);
    let rawRssi = parseInt(trueRssiHex, 16);
    let trueRssi = (rawRssi / 2) - 121; // Match the old Gateway's exact dBm formula

    const networkLvl = parseInt(headerHex.slice(20, 22), 16) || 1;
    const hops = parseInt(headerHex.slice(22, 24), 16) || 1;
    const latency = parseInt(headerHex.slice(24, 26), 16) || 2;

    // 4. EXTRACT THE PAYLOAD DATA (Little-Endian)
    let expectedPayloadChars = 0;
    if (packetType === 1) expectedPayloadChars = 58 * 2;
    else if (packetType === 2) expectedPayloadChars = 106 * 2;
    else if (packetType === 4) expectedPayloadChars = 12 * 2;

    if (buf.length < startIndex + expectedPayloadChars) {
        break; // Wait for the rest of the serial chunk
    }

    const frameHex = buf.slice(startIndex, startIndex + expectedPayloadChars);
    buf = buf.slice(startIndex + expectedPayloadChars); 

    const bytes = [];
    for (let i = 0; i < frameHex.length; i += 2) {
        bytes.push(parseInt(frameHex.slice(i, i + 2), 16));
    }
    const view = new DataView(new Uint8Array(bytes).buffer);

    let extractedData = {};
    let messageDetail = "unknown";

    if (packetType === 1) {
        messageDetail = "sensor_telemetry";

        // Mapped exactly to sensor_telegram_t from sensors.h
        extractedData = {
            AirTemperature:      view.getFloat32(6,  true),
            AirPressure:         view.getFloat32(10, true),
            HumidityTemperature: view.getFloat32(14, true),
            Humidity:            view.getFloat32(18, true),
            LightALS:            view.getUint32(22,  true), // Parsed as integer based on C-struct behavior
            GASCO2:              view.getFloat32(26, true),
            GASTemperature:      view.getFloat32(30, true),
            GASHumidity:         view.getFloat32(34, true),
            GASNH3:              view.getFloat32(38, true),
            GASCO:               view.getFloat32(42, true),
            GASNO2:              view.getFloat32(46, true),
            BoardTemperature:    view.getFloat32(50, true),
            PT100Temperature:    view.getFloat32(54, true)
        };
    } else if (packetType === 2) {
        messageDetail = "weight_telemetry";
        const samples = [];
        for (let i = 6; i + 1 < bytes.length; i += 2) {
            samples.push(view.getUint16(i, true)); // Payload stays LE
        }
        extractedData = {
            count: samples.length,
            mean_weight: samples.reduce((a, b) => a + b, 0) / samples.length
        };
    } else if (packetType === 4) {
        messageDetail = "device_startup";
        extractedData = {
            hardware_mac: frameHex.slice(4, 20), 
            firmware: view.getUint16(10, true) // Payload stays LE
        };
    }

    // 5. BUILD THE FAI CLOUD ENVELOPE
    out.push({
        topic: `gateway/${gatewayId}/tinymesh/out`,
        payload: {
            "_meta": { "received": new Date().toISOString() },
            "block": 0,
            "data": JSON.stringify(extractedData), 
            "detail": messageDetail,               
            "hops": hops,
            "latency": latency,
            "network_lvl": networkLvl,
            "packet_num": Math.floor(Math.random() * 65535),
            "rssi": trueRssi, 
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid,  
            "raw_hex": frameHex 
        }
    });
}

context.set('buf', buf);

if (out.length === 0) return null;
if (out.length === 1) return out[0];
return [out];

// ── FAI Gateway Parser (v3.1 - Raw Payload, Correct UID) ──

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const TARGET_CLOUD_SID = 16777216;

let incoming = "";
if (Buffer.isBuffer(msg.payload))           incoming = msg.payload.toString('hex');
else if (msg.payload?.hex)                  incoming = msg.payload.hex;
else if (typeof msg.payload === 'string')   incoming = msg.payload;
else return null;

let buf = (context.get('buf') || '') + incoming.replace(/\s+/g, '');
const out = [];

if (buf.length > 8192) {
    context.set('buf', '');
    node.warn("Buffer overflow — flushed");
    return null;
}

while (buf.length > 0) {
    const sensorIdx = buf.indexOf("013a");
    const weightIdx = buf.indexOf("026a");
    const aliveIdx  = buf.indexOf("040c");

    const candidates = [
        { type: 1, idx: sensorIdx },
        { type: 2, idx: weightIdx },
        { type: 4, idx: aliveIdx }
    ].filter(c => c.idx !== -1);

    if (!candidates.length) {
        if (buf.length > 50) buf = buf.slice(-50);
        break;
    }

    const { type: packetType, idx: startIndex } =
        candidates.reduce((a, b) => a.idx < b.idx ? a : b);

    // Need 18-byte (36 hex char) header before the payload signature
    if (startIndex < 36) { buf = buf.slice(startIndex + 2); continue; }

    const headerHex = buf.slice(startIndex - 36, startIndex);

    // UID: bytes 5-8 of header, Big-Endian
    const trueUidHex = headerHex.slice(10, 18);
    if (!/^[0-9a-fA-F]{8}$/.test(trueUidHex)) {
        buf = buf.slice(startIndex + 2);
        continue;
    }
    const dynamicUid = Buffer.from(trueUidHex, 'hex').readUInt32BE(0);

    // RSSI: raw integer as the backend expects (same format tinymesh-edge sent)
    const rawRssi = parseInt(headerHex.slice(18, 20), 16);

    const networkLvl = parseInt(headerHex.slice(20, 22), 16) || 1;
    const hops       = parseInt(headerHex.slice(22, 24), 16) || 1;
    const latency    = parseInt(headerHex.slice(24, 26), 16) || 2;

    const payloadLen = packetType === 1 ? 58 : packetType === 2 ? 106 : 12;
    const needed = startIndex + payloadLen * 2;
    if (buf.length < needed) break;

    const frameHex = buf.slice(startIndex, needed);
    buf = buf.slice(needed);

    out.push({
        topic: `gateway/${gatewaySerial}/tinymesh/out`,
        payload: {
            "_meta": { "received": new Date().toISOString().split('.')[0] + '+00:00' },
            "block":       0,
            "data":        frameHex,   // Raw C-struct hex — backend decodes this itself
            "detail":      "serial",
            "hops":        hops,
            "latency":     latency,
            "network_lvl": networkLvl,
            "packet_num":  Math.floor(Math.random() * 65535),
            "rssi":        rawRssi,    // Raw integer, not dBm — matches tinymesh-edge format
            "sid":         TARGET_CLOUD_SID,
            "type":        "event",
            "uid":         dynamicUid
        }
    });
}

context.set('buf', buf);
if (!out.length) return null;
return out.length === 1 ? out[0] : out;

// ── FAI wMBus Extractor (MC100 Format Match) ──

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

if (!Buffer.isBuffer(msg.payload)) return null;

const hexData = msg.payload.toString('hex').toLowerCase();
const base64Raw = msg.payload.toString('base64');

if (hexData.length < 50) return null;

// ── PARSE HEADER FIELDS ──
const lField = parseInt(hexData.substring(0, 2), 16);
const cField = parseInt(hexData.substring(2, 4), 16);

// Manufacturer (bytes 2-3, little-endian → 15-bit decode)
const manHex = hexData.substring(6, 8) + hexData.substring(4, 6);
const manInt = parseInt(manHex, 16);
const manufacturer =
    String.fromCharCode(((manInt >> 10) & 0x001F) + 64) +
    String.fromCharCode(((manInt >> 5)  & 0x001F) + 64) +
    String.fromCharCode((manInt & 0x001F) + 64);

// Device ID (bytes 4-7, little-endian BCD reversal)
const idHex = hexData.substring(8, 16);
const serialNumber = idHex.substring(6, 8) +
    idHex.substring(4, 6) +
    idHex.substring(2, 4) +
    idHex.substring(0, 2);

// Version and device type bytes
const version = parseInt(hexData.substring(16, 18), 16);
const ciField  = parseInt(hexData.substring(20, 22), 16);

// Full ID as the MC100 sends it (manufacturer + serial)
const fullId = manufacturer + serialNumber;

// RSSI — RC1180 with RSSI mode off means we don't have it;
// send a reasonable placeholder or omit
const rssiDbm = -52; // placeholder; adjust if you enable RSSI on dongle

msg.topic = `gateway/${gatewaySerial}/wmbus/out`;
msg.payload = {
    "_meta": {
        "received": new Date().toISOString().split('.')[0] + '+00:00',
        "receiver_id": "0000000000000000",
        "rssi": rssiDbm
    },
    "data": {
        "AField":       idHex.toUpperCase() + hexData.substring(16, 28).toUpperCase(),
        "CField":       cField,
        "CIField":      ciField,
        "ID":           "18" + serialNumber,
        "LField":       lField,
        "MField":       manInt,
        "Manufacturer": manufacturer,
        "SerialNumber": serialNumber
    },
    "raw":  base64Raw,
    "type": "wmbus"
};

return msg;

let joined = msg.payload;

// Safely set default values so it never crashes
let voltage = 0;
let amps = 0;
let partNumber = "Unknown CG Meter";
let serial = "Unknown";

// Helper function: Node-RED Modbus sometimes puts the array inside '.data'
function getArray(payloadPart) {
    if (!payloadPart) return null;
    return payloadPart.data ? payloadPart.data : payloadPart;
}

let volArr = getArray(joined.voltage);
let ampArr = getArray(joined.amps);
let modArr = getArray(joined.model);
let serArr = getArray(joined.serial);

// 1. Parse Voltage (Address 0)
if (volArr && volArr.length >= 2) {
    let rawVolts = (volArr[1] << 16) | volArr[0];
    voltage = rawVolts / 10;
}

// 2. Parse Amps (Address 12)
if (ampArr && ampArr.length >= 2) {
    let rawAmps = (ampArr[1] << 16) | ampArr[0];
    amps = rawAmps / 1000;
}

// 3. Identify Device Type (Address 11)
if (modArr && modArr.length >= 1) {
    let modelCode = modArr[0];
    if (modelCode === 332) partNumber = "EM330-DIN AV5";
    else if (modelCode === 341) partNumber = "EM340-DIN AV2";
    else partNumber = "Model Code: " + modelCode;
}

// 4. Parse Serial Number (Address 20480)
if (serArr) {
    serial = "";
    serArr.forEach(reg => {
        serial += String.fromCharCode(reg & 0xFF); // Extract LSB to ASCII
    });
}

// Build the exact MC100 output payload
msg.payload = {
    "DateTime": new Date().toISOString(),
    "Amp": parseFloat(amps.toFixed(3)),
    "AmpHour": 0, 
    "Voltage": parseFloat(voltage.toFixed(1)),
    "State": "",
    "Partnumber": partNumber,
    "Serialnumber": serial.trim(), 
    "FirmwareRevision": "0.0-1",
    "Type": "modbus-meter",
    "Meta": null
};

// --- NEW CODE: Build the exact MQTT Topic ---
// Grab the Gateway Serial from the Docker environment variables
let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

// Format: gateway/A100000155081224/power/out
msg.topic = `gateway/${gatewaySerial}/power/out`;

return msg;

let joined = msg.payload;

// Safely set default values so it never crashes
let voltage = 0;
let amps = 0;
let partNumber = "TIP SINUS";
let serial = "Unknown";

// Helper function: Node-RED Modbus sometimes puts the array inside '.data'
function getArray(payloadPart) {
    if (!payloadPart) return null;
    return payloadPart.data ? payloadPart.data : payloadPart;
}

// Notice I removed the '#' from the Serial name here!
let volArr = getArray(joined.voltage);
let ampArr = getArray(joined.amps);
let serArr = getArray(joined.serial);

// 1. Parse Voltage (Address 34)
if (volArr && volArr.length >= 2) {
    let rawVolts = (volArr[0] * 65536) + volArr[1];
    voltage = rawVolts / 1000;
}

// 2. Parse Amps (Address 36)
if (ampArr && ampArr.length >= 2) {
    let rawAmps = (ampArr[0] * 65536) + ampArr[1];
    amps = rawAmps / 1000;
}

// 3. Parse Serial Number (Address 4)
if (serArr && serArr.length >= 2) {
    let highHex = serArr[0].toString(16).padStart(4, '0');
    let lowHex = serArr[1].toString(16).padStart(4, '0');
    let rawSerial = (highHex + lowHex).toUpperCase();

    // Convert to integer to strip leading zeros, then back to string
    serial = parseInt(rawSerial, 10).toString(); 
}
// Build the exact MC100 output payload
msg.payload = {
    "DateTime": new Date().toISOString(),
    "Amp": parseFloat(amps.toFixed(3)),
    "AmpHour": 0, 
    "Voltage": parseFloat(voltage.toFixed(1)),
    "State": "",
    "Partnumber": partNumber,
    "Serialnumber": serial.trim(), 
    "FirmwareRevision": "0.0-1",
    "Type": "modbus-meter",
    "Meta": null
};

// --- Build the exact MQTT Topic ---
let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
msg.topic = `gateway/${gatewaySerial}/power/out`;

return msg;

let raw = msg.payload.data || msg.payload;

if (raw && raw.length >= 2) {
    // 1. Stitch the two 16-bit Modbus registers into a 32-bit signed integer
    let weight = (raw[0] << 16) | raw[1];

    // 2. Dynamically pull the device's hardware serial from the local .env
    let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

    // 3. Format the payload to exactly match your Tinymesh backend architecture
    msg.payload = {
        "gateway_id": gatewaySerial,
        "sensor_type": "silo_weight",
        "timestamp": new Date().toISOString(),
        "data": {
            "weight_kg": weight
        }
    };

    // 4. Assign the standard routing topic for your MQTT broker
    msg.topic = `gateway/${gatewaySerial}/telemetry`;

    return msg;
}

// If the Modbus read fails or returns empty, stop the flow to prevent crashing the backend
return null;

const raw = msg.payload?.data ?? msg.payload;

if (!Array.isArray(raw) || raw.length < 2) {
    return null;
}

// ADS301 MSV: two 16-bit words, high word first, signed 32-bit result
const highWord = Number(raw[0]) & 0xFFFF;
const lowWord = Number(raw[1]) & 0xFFFF;

let displayUnits = (highWord * 0x10000) + lowWord;

if (displayUnits >= 0x80000000) {
    displayUnits -= 0x100000000;
}

// Set to 1 for 1 kg divisions.
// Set to 10 if the ADS301 is configured for 0.1 kg divisions.
const unitsPerKg = 1;
const weightKg = displayUnits / unitsPerKg;

const gatewayId = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

// This parser is permanently for physical Silo 1.
const siloNumber = 2;
const siloId = String(siloNumber).padStart(2, "0");

const deviceSerialNumber = `${gatewayId}_silo_${siloId}`;

// Match the backend schema exactly.
msg.payload = {
    gateway_id: gatewayId,
    device_serial_number: deviceSerialNumber,
    sensor_type: "silo_weight",
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, "Z"),
    data: {
        weight_kg: weightKg
    }
};

msg.topic = `gateway/${gatewayId}/silo/${deviceSerialNumber}/telemetry`;

return msg;

// ── FAI Gateway Parser (v7.2 - Raw C-Struct Forger, matches sensors.h spec + GASCO2 workaround) ──
//
// Key fix vs v6.0: the backend does NOT want JSON in `data`. It wants the raw
// hex-encoded C-struct (sensor_telegram_t / weight array), exactly like the
// physical Tinymesh hardware sent it, with detail:"serial".
//
// Per the official sensors.h spec:
//   Type 0x01 (Env, 58 bytes): all fields Little-Endian Float32, except
//     LightALS (bytes 22-25) which is Uint32 LE.
//   Type 0x02 (Weight, 106 bytes): 50x Uint16 LE samples starting at byte 6.
//
// CONFIRMED WORKAROUND: the third-party backend's decoder reads GASCO2
// (bytes 26-29) as Uint32, not Float32 as the spec documents. We can't patch
// the backend, so this parser writes GASCO2 as a raw integer to match what
// the backend actually does, not what the spec says it should do. See the
// inline comment at that field for the verification details.

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const TARGET_CLOUD_SID = 16777216;

if (!msg.payload || !msg.payload.deviceInfo || !msg.payload.data) return null;

// ── UID: last 4 bytes of DevEUI, Big-Endian (matches dynamicUid convention) ──
const devEui = msg.payload.deviceInfo.devEui;
const uidHex = devEui.slice(-8);
const dynamicUid = parseInt(uidHex, 16);

// ── Decode the LoRa binary payload ──
// Payload is now 22 bytes (was 14, was originally 10): the Arduino sketch
// now also transmits humidity and pressure from the already-installed
// BME280 (it measures both, the code just wasn't reading them before).
// Layout, all Little-Endian:
//   bytes 0-3:   temperature (float)
//   bytes 4-5:   co2 ppm (uint16)
//   bytes 6-9:   scale weight (float)
//   bytes 10-13: light lux (float)
//   bytes 14-17: humidity %RH (float)   <-- NEW
//   bytes 18-21: pressure hPa (float)   <-- NEW
const buf = Buffer.from(msg.payload.data, 'base64');
if (buf.length < 22) return null;

const temp     = buf.readFloatLE(0);   // °C
const co2      = buf.readUInt16LE(4);  // ppm
const weight   = buf.readFloatLE(6);   // g
const lux      = buf.readFloatLE(10);  // lx
const humidity = buf.readFloatLE(14);  // %RH
const pressure = buf.readFloatLE(18);  // hPa

// ── RSSI & meta (raw integer, matching tinymesh-edge convention: Math.abs) ──
let bestRssi = -120;
if (msg.payload.rxInfo && msg.payload.rxInfo.length > 0) {
    bestRssi = Math.max(...msg.payload.rxInfo.map(rx => rx.rssi));
}
const rawRssi = Math.abs(bestRssi);
const timestamp = (msg.payload.time || new Date().toISOString()).split('.')[0] + '+00:00';

const outMessages = [];

// ==========================================
// FORGE PACKET 1: TYPE 0x01 (ENVIRONMENTAL)
// Length: 58 bytes | Signature: 013a
// Layout matches sensor_telegram_t exactly, Little-Endian floats per sensors.h spec
// ==========================================
const envBuf = Buffer.alloc(58, 0);
envBuf.writeUInt8(0x01, 0); // Byte 0: Type
envBuf.writeUInt8(0x3a, 1); // Byte 1: Length (58)

// Bytes 2-5 reserved/unused in struct — left as 0x00

envBuf.writeFloatLE(temp, 6);    // AirTemperature      (bytes 6-9)
envBuf.writeFloatLE(pressure, 10); // AirPressure (bytes 10-13) — now real BME280 hPa reading.
                                  // UNVERIFIED against backend: AirTemperature at byte 6 is
                                  // confirmed correct as Float32, but we haven't specifically
                                  // checked AirPressure. If Grafana shows nonsense here, run the
                                  // same bit-pattern check used for GASCO2.
envBuf.writeFloatLE(temp, 14);   // HumidityTemperature  (bytes 14-17)  — BME280 has one temp sensor,
                                  // reused here since there's no separate humidity-specific probe
envBuf.writeFloatLE(humidity, 18); // Humidity (bytes 18-21) — now real BME280 %RH reading.
                                  // Also unverified against backend — check Grafana after deploy.
envBuf.writeUInt32LE(Math.max(0, Math.round(lux)), 22); // LightALS (bytes 22-25) — now real VEML7700
                                            // lux data. Written as Uint32 per spec (rounded, floor
                                            // 0 since lux can't be negative). UNVERIFIED: we found
                                            // GASCO2 doesn't match its documented type, so once this
                                            // is live, check Grafana the same way — if LightALS shows
                                            // a nonsense number, the backend likely also reads this
                                            // field as a different type than Uint32 and needs the
                                            // same bit-pattern diagnosis we did for GASCO2.
envBuf.writeUInt32LE(Math.round(co2), 26); // GASCO2 (bytes 26-29) — WORKAROUND: spec sheet says
                                            // Float32 here, but the backend's fixed/third-party
                                            // decoder actually reads this field as Uint32 (same
                                            // type as LightALS next to it). Confirmed by reverse-
                                            // engineering: writing 476.0 as Float32 produced
                                            // 1139671040 in Grafana — the exact bit pattern of
                                            // that float reinterpreted as a raw uint32. Since the
                                            // backend can't be patched, we match its real behavior
                                            // instead of the documented spec: write the ppm value
                                            // directly as an integer.
envBuf.writeFloatLE(0.0, 30);    // GASTemperature       (bytes 30-33)
envBuf.writeFloatLE(0.0, 34);    // GASHumidity          (bytes 34-37)
envBuf.writeFloatLE(0.0, 38);    // GASNH3               (bytes 38-41)
envBuf.writeFloatLE(0.0, 42);    // GASCO                (bytes 42-45)
envBuf.writeFloatLE(0.0, 46);    // GASNO2               (bytes 46-49)
envBuf.writeFloatLE(temp, 50);   // BoardTemperature     (bytes 50-53)  — reuse BME280 temp
envBuf.writeFloatLE(temp, 54);   // PT100Temperature     (bytes 54-57)  — reuse BME280 temp

outMessages.push({
    topic: `gateway/${gatewaySerial}/tinymesh/out`,
    payload: {
        "_meta": { "received": timestamp },
        "block": 0,
        "data": envBuf.toString('hex'), // RAW HEX — backend decodes this itself
        "detail": "serial",             // matches the proven working contract
        "hops": 1,
        "latency": 2,
        "network_lvl": 1,
        "packet_num": Math.floor(Math.random() * 65535), // bypass cloud dedup
        "rssi": rawRssi,
        "sid": TARGET_CLOUD_SID,
        "type": "event",
        "uid": dynamicUid
    }
});

// ==========================================
// FORGE PACKET 2: TYPE 0x02 (WEIGHT ARRAY)
// Length: 106 bytes | Signature: 026a
// Array of 50x UInt16, Little-Endian (per reference decoder: "Payload stays LE")
// ==========================================
if (weight > 0.01 || weight < -0.01) {
    const wBuf = Buffer.alloc(106, 0);
    wBuf.writeUInt8(0x02, 0); // Byte 0: Type
    wBuf.writeUInt8(0x6a, 1); // Byte 1: Length (106)

    const wInt = Math.abs(Math.round(weight));

    for (let i = 0; i < 50; i++) {
        wBuf.writeUInt16LE(wInt, 6 + (i * 2));
    }

    outMessages.push({
        topic: `gateway/${gatewaySerial}/tinymesh/out`,
        payload: {
            "_meta": { "received": timestamp },
            "block": 0,
            "data": wBuf.toString('hex'), // RAW HEX, same as packet 1
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,
            "packet_num": Math.floor(Math.random() * 65535),
            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    });
}

return [ outMessages ];

// ── FAI Gateway Parser v9.0 — Individual Weight Events ──────────────────────
//
// Arduino input:
//   One 50-byte LoRaWAN packet every approximately 3 minutes.
//
//   Byte 0:       protocol version
//   Byte 1:       number of weight samples
//   Bytes 2-3:    batch number, UInt16 LE
//   Bytes 4-39:   18 × weight readings, UInt16 LE
//   Bytes 40-41:  temperature × 100, Int16 LE
//   Bytes 42-43:  CO2 ppm, UInt16 LE
//   Bytes 44-45:  light lux, UInt16 LE
//   Bytes 46-47:  humidity × 100, UInt16 LE
//   Bytes 48-49:  pressure × 10, UInt16 LE
//
// Weight behaviour:
//   - The 18 Arduino readings are genuine spot readings taken 10 seconds apart.
//   - Each valid reading becomes a separate backend Type 0x02 event.
//   - Each Type 0x02 event contains the one weight repeated across all 50
//     legacy array positions.
//   - The 18 backend event timestamps are reconstructed at 10-second intervals.
//   - 0xFFFF means invalid and that specific event is omitted.
//   - Genuine 0 g readings are retained.
//
// Backend output:
//   Type 0x01: environmental packet, 58 bytes, signature 013a.
//   Type 0x02: weight packet, 106 bytes, signature 026a.
//
// There is no longer a cross-message weight queue.

// ============================================================================
// Configuration
// ============================================================================

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

const TARGET_CLOUD_SID = 16777216;

const EXPECTED_PAYLOAD_LENGTH = 50;
const EXPECTED_VERSION = 1;

const MAX_WEIGHT_SAMPLES = 18;
const WEIGHT_INTERVAL_MS = 10000;

const INVALID_WEIGHT = 0xFFFF;

// Retain a small duplicate history for each device.
const RECENT_MESSAGE_HISTORY = 64;
const STATE_NAMESPACE = "faiParserV90";

// ============================================================================
// Validate incoming ChirpStack message
// ============================================================================

if (
    !msg.payload ||
    !msg.payload.deviceInfo ||
    !msg.payload.deviceInfo.devEui ||
    msg.payload.data === undefined ||
    msg.payload.data === null
) {
    node.warn(
        "Invalid ChirpStack message: required payload fields are missing"
    );

    return null;
}

// ============================================================================
// Device identity
// ============================================================================

const devEui =
    String(msg.payload.deviceInfo.devEui).toUpperCase();

const uidHex =
    devEui.slice(-8);

if (!/^[0-9A-F]{8}$/.test(uidHex)) {
    node.warn(`Invalid DevEUI: ${devEui}`);
    return null;
}

const dynamicUid =
    parseInt(uidHex, 16);

if (!Number.isFinite(dynamicUid)) {
    node.warn(
        `Unable to calculate UID from DevEUI: ${devEui}`
    );

    return null;
}

// ============================================================================
// Decode compact LoRaWAN payload
// ============================================================================

let buf;

try {
    if (Buffer.isBuffer(msg.payload.data)) {
        buf = msg.payload.data;
    } else {
        buf = Buffer.from(
            String(msg.payload.data),
            "base64"
        );
    }
} catch (error) {
    node.warn(
        `Unable to decode LoRa payload from ${devEui}: ` +
        error.message
    );

    return null;
}

if (buf.length !== EXPECTED_PAYLOAD_LENGTH) {
    node.warn(
        `Unexpected payload length from ${devEui}: ` +
        `${buf.length} bytes; expected ${EXPECTED_PAYLOAD_LENGTH}`
    );

    return null;
}

// ============================================================================
// Decode header
// ============================================================================

const protocolVersion =
    buf.readUInt8(0);

const sampleCount =
    buf.readUInt8(1);

const batchNumber =
    buf.readUInt16LE(2);

if (protocolVersion !== EXPECTED_VERSION) {
    node.warn(
        `Unsupported payload version from ${devEui}: ` +
        `${protocolVersion}; expected ${EXPECTED_VERSION}`
    );

    return null;
}

if (
    sampleCount === 0 ||
    sampleCount > MAX_WEIGHT_SAMPLES
) {
    node.warn(
        `Invalid weight sample count from ${devEui}: ` +
        sampleCount
    );

    return null;
}

if (sampleCount !== MAX_WEIGHT_SAMPLES) {
    node.warn(
        `Partial weight batch from ${devEui}: ` +
        `${sampleCount}/${MAX_WEIGHT_SAMPLES}`
    );
}

// ============================================================================
// Duplicate uplink protection
// ============================================================================
//
// Prefer ChirpStack's frame counter when available. Otherwise use the complete
// compact payload and Arduino batch number.

const recentMessagesKey =
    `${STATE_NAMESPACE}_recent_${devEui}`;

let recentMessages =
    global.get(recentMessagesKey);

if (!Array.isArray(recentMessages)) {
    recentMessages = [];
}

const frameCounter =
    Number(msg.payload.fCnt);

const messageSignature =
    Number.isInteger(frameCounter)
        ? `fcnt:${frameCounter}`
        : `batch:${batchNumber}:${buf.toString("hex")}`;

if (recentMessages.includes(messageSignature)) {
    node.warn(
        `Ignoring duplicate LoRa batch ${batchNumber} ` +
        `from ${devEui}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `duplicate batch ${batchNumber}`
    });

    return null;
}

recentMessages.push(messageSignature);

if (recentMessages.length > RECENT_MESSAGE_HISTORY) {
    recentMessages =
        recentMessages.slice(-RECENT_MESSAGE_HISTORY);
}

global.set(
    recentMessagesKey,
    recentMessages
);

// ============================================================================
// Decode environmental data
// ============================================================================

const temp =
    buf.readInt16LE(40) / 100.0;

const co2 =
    buf.readUInt16LE(42);

const lux =
    buf.readUInt16LE(44);

const humidity =
    buf.readUInt16LE(46) / 100.0;

const pressure =
    buf.readUInt16LE(48) / 10.0;

// ============================================================================
// RSSI
// ============================================================================

let bestRssi = -120;

if (
    Array.isArray(msg.payload.rxInfo) &&
    msg.payload.rxInfo.length > 0
) {
    const validRssiValues =
        msg.payload.rxInfo
            .map(rx => Number(rx.rssi))
            .filter(value => Number.isFinite(value));

    if (validRssiValues.length > 0) {
        bestRssi =
            Math.max(...validRssiValues);
    }
}

const rawRssi =
    Math.abs(bestRssi);

// ============================================================================
// Timestamp helpers
// ============================================================================
//
// Preserve the previously proven behaviour by using Node-RED processing time
// as the time of the newest sample.
//
// For an 18-reading batch:
//
//   sample 0  = newest time minus 170 seconds
//   sample 1  = newest time minus 160 seconds
//   ...
//   sample 17 = newest time

const newestSampleTime =
    new Date();

function formatBackendTimestamp(date) {
    return (
        date.toISOString().split(".")[0] +
        "+00:00"
    );
}

// ============================================================================
// Backend message helper
// ============================================================================

const outMessages = [];

const usedPacketNumbers =
    new Set();

function nextPacketNumber() {
    let packetNumber;

    do {
        packetNumber =
            Math.floor(Math.random() * 65536);
    } while (usedPacketNumbers.has(packetNumber));

    usedPacketNumbers.add(packetNumber);

    return packetNumber;
}

function makeBackendMessage(
    hexData,
    receivedTimestamp
) {
    return {
        topic:
            `gateway/${gatewaySerial}/tinymesh/out`,

        payload: {
            "_meta": {
                "received": receivedTimestamp
            },

            "block": 0,
            "data": hexData,
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,
            "packet_num": nextPacketNumber(),
            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    };
}

// ============================================================================
// Forge one Type 0x02 packet for each valid weight reading
//
// Type:      0x02
// Length:    106 bytes
// Signature: 026a
// ============================================================================

let validWeightEvents = 0;
let invalidWeightEvents = 0;
let genuineZeroEvents = 0;

let firstValidWeight = null;
let lastValidWeight = null;

let firstWeightTimestamp = null;
let lastWeightTimestamp = null;

for (let i = 0; i < sampleCount; i++) {
    const weight =
        buf.readUInt16LE(4 + (i * 2));

    const ageFromNewestMs =
        (sampleCount - 1 - i) *
        WEIGHT_INTERVAL_MS;

    const sampleTime =
        new Date(
            newestSampleTime.getTime() -
            ageFromNewestMs
        );

    const sampleTimestamp =
        formatBackendTimestamp(sampleTime);

    if (weight === INVALID_WEIGHT) {
        invalidWeightEvents++;

        node.warn(
            `Skipping invalid weight — ` +
            `device=${devEui}, ` +
            `batch=${batchNumber}, ` +
            `sample=${i + 1}/${sampleCount}, ` +
            `timestamp=${sampleTimestamp}`
        );

        continue;
    }

    // Preserve genuine zeroes and reserve 0xFFFF for invalid readings.
    const outputWeight =
        Math.min(
            65534,
            Math.max(
                0,
                Math.round(weight)
            )
        );

    if (outputWeight === 0) {
        genuineZeroEvents++;
    }

    const wBuf =
        Buffer.alloc(106, 0);

    wBuf.writeUInt8(0x02, 0);
    wBuf.writeUInt8(0x6A, 1);

    // Bytes 2-5 remain reserved and zero-filled.
    //
    // Repeat this single spot reading across the fixed legacy 50-value
    // structure. The backend associates the complete telegram with the
    // timestamp above.

    for (let j = 0; j < 50; j++) {
        wBuf.writeUInt16LE(
            outputWeight,
            6 + (j * 2)
        );
    }

    outMessages.push(
        makeBackendMessage(
            wBuf.toString("hex"),
            sampleTimestamp
        )
    );

    if (firstValidWeight === null) {
        firstValidWeight =
            outputWeight;

        firstWeightTimestamp =
            sampleTimestamp;
    }

    lastValidWeight =
        outputWeight;

    lastWeightTimestamp =
        sampleTimestamp;

    validWeightEvents++;
}

// ============================================================================
// Forge Type 0x01 environmental packet
//
// Type:      0x01
// Length:    58 bytes
// Signature: 013a
// ============================================================================

const envBuf =
    Buffer.alloc(58, 0);

envBuf.writeUInt8(0x01, 0);
envBuf.writeUInt8(0x3A, 1);

// Bytes 2-5 remain reserved and zero-filled.

envBuf.writeFloatLE(
    temp,
    6
);                                      // AirTemperature

envBuf.writeFloatLE(
    pressure,
    10
);                                      // AirPressure

envBuf.writeFloatLE(
    temp,
    14
);                                      // HumidityTemperature

envBuf.writeFloatLE(
    humidity,
    18
);                                      // Humidity

envBuf.writeUInt32LE(
    Math.min(
        0xFFFFFFFF,
        Math.max(
            0,
            Math.round(lux)
        )
    ),
    22
);                                      // LightALS

// Confirmed backend workaround:
// GASCO2 must be written as UInt32 rather than Float32.
envBuf.writeUInt32LE(
    Math.min(
        0xFFFFFFFF,
        Math.max(
            0,
            Math.round(co2)
        )
    ),
    26
);                                      // GASCO2

envBuf.writeFloatLE(0.0, 30);            // GASTemperature
envBuf.writeFloatLE(0.0, 34);            // GASHumidity
envBuf.writeFloatLE(0.0, 38);            // GASNH3
envBuf.writeFloatLE(0.0, 42);            // GASCO
envBuf.writeFloatLE(0.0, 46);            // GASNO2
envBuf.writeFloatLE(temp, 50);           // BoardTemperature
envBuf.writeFloatLE(temp, 54);           // PT100Temperature

const environmentalTimestamp =
    formatBackendTimestamp(newestSampleTime);

// Add the environmental packet after the chronological weight events.
outMessages.push(
    makeBackendMessage(
        envBuf.toString("hex"),
        environmentalTimestamp
    )
);

// ============================================================================
// Diagnostics
// ============================================================================

node.warn(
    `BATCH DECODED — ` +
    `device=${devEui}, ` +
    `batch=${batchNumber}, ` +
    `samples=${sampleCount}, ` +
    `validWeights=${validWeightEvents}, ` +
    `invalidWeights=${invalidWeightEvents}, ` +
    `genuineZeros=${genuineZeroEvents}`
);

if (validWeightEvents > 0) {
    node.warn(
        `WEIGHT EVENTS CREATED — ` +
        `device=${devEui}, ` +
        `count=${validWeightEvents}, ` +
        `firstWeight=${firstValidWeight}, ` +
        `firstTime=${firstWeightTimestamp}, ` +
        `lastWeight=${lastValidWeight}, ` +
        `lastTime=${lastWeightTimestamp}`
    );
}

node.warn(
    `PARSER OUTPUT — ` +
    `device=${devEui}, ` +
    `messages=${outMessages.length}, ` +
    `weightMessages=${validWeightEvents}, ` +
    `environmentMessages=1`
);

node.status({
    fill:
        invalidWeightEvents > 0
            ? "yellow"
            : "green",

    shape: "dot",

    text:
        `${validWeightEvents} weights + 1 env`
});

// ============================================================================
// Send all generated messages through output 1
// ============================================================================
//
// With 18 valid weights, this sends 19 messages:
//
//   18 × Type 0x02 weight packets
//    1 × Type 0x01 environmental packet

node.send([outMessages]);

return null;

// ── FAI Gateway: Silo Weight Parser (Production) ──

// 1. Get the physical gateway's identity
let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

// 2. Extract the raw Modbus payload
let raw = msg.payload.data || msg.payload;

if (raw && raw.length >= 2) {
    // 3. Bitwise shift to combine the two 16-bit registers into a 32-bit integer
    let weight = (raw[0] << 16) | raw[1];

    // 4. Identify WHICH silo this is based on the Modbus Slave Address (1 to 4)
    // node-red-contrib-modbus attaches the unitid to the request object automatically
    let slaveAddress = (msg.modbusRequest && msg.modbusRequest.unitid) ? msg.modbusRequest.unitid : 1; 
    let deviceId = "silo_" + slaveAddress.toString().padStart(2, '0'); // e.g., "silo_01", "silo_02"

    // 5. Build the clean, decoupled JSON payload for the backend
    msg.payload = {
        "gateway_id": gatewaySerial,
        "device_id": deviceId,
        "sensor_type": "silo_weight",
        "timestamp": new Date().toISOString(),
        "data": {
            "weight_kg": weight,
            "modbus_address": slaveAddress
        }
    };

    // 6. Route it to the dedicated Silo topic
    msg.topic = `gateway/${gatewaySerial}/silo/${deviceId}/telemetry`;

    return msg;
}

// Stop the flow if the reading failed or is empty
return null;

// ── FAI Gateway: Silo Weight Parser ──
let raw = msg.payload.data || msg.payload;

if (raw && raw.length >= 2) {
    // 1. Stitch the two 16-bit Modbus registers into a 32-bit signed integer
    let weight = (raw[0] << 16) | raw[1];

    // NOTE: If your scale division (DIV) in the JB is set to 0.1kg, 
    // you must divide by 10 here (weight = weight / 10.0). 
    // Assuming DIV = 1kg for now.

    // 2. Identify identity and Modbus slave address
    let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
    let slaveAddress = (msg.modbusRequest && msg.modbusRequest.unitid) ? msg.modbusRequest.unitid : 1; 
    let deviceId = "silo_" + slaveAddress.toString().padStart(2, '0');

    // 3. Build the clean JSON payload
    msg.payload = {
        "gateway_id": gatewaySerial,
        "device_id": deviceId,
        "sensor_type": "silo_weight",
        "timestamp": new Date().toISOString(),
        "data": {
            "weight_kg": weight,
            "modbus_address": slaveAddress
        }
    };

    // 4. Route it to the dedicated Silo topic
    msg.topic = `gateway/${gatewaySerial}/silo/${deviceId}/telemetry`;

    return msg;
}

// Stop the flow if the reading failed or is empty
return null;

const raw = msg.payload?.data ?? msg.payload;

if (!Array.isArray(raw) || raw.length < 2) {
    return null;
}

// ADS301 MSV: two 16-bit words, high word first, signed 32-bit result
const highWord = Number(raw[0]) & 0xFFFF;
const lowWord = Number(raw[1]) & 0xFFFF;

let displayUnits = (highWord * 0x10000) + lowWord;

if (displayUnits >= 0x80000000) {
    displayUnits -= 0x100000000;
}

// Set to 1 for 1 kg divisions.
// Set to 10 if the ADS301 is configured for 0.1 kg divisions.
const unitsPerKg = 1;
const weightKg = displayUnits / unitsPerKg;

const gatewayId = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

// This parser is permanently for physical Silo 1.
const siloNumber = 1;
const siloId = String(siloNumber).padStart(2, "0");

const deviceSerialNumber = `${gatewayId}_silo_${siloId}`;

// Match the backend schema exactly.
msg.payload = {
    gateway_id: gatewayId,
    device_serial_number: deviceSerialNumber,
    sensor_type: "silo_weight",
    timestamp: new Date().toISOString().replace(/\.\d{3}Z$/, "Z"),
    data: {
        weight_kg: weightKg
    }
};

msg.topic = `gateway/${gatewayId}/silo/${deviceSerialNumber}/telemetry`;

return msg;

let raw = msg.payload.data || msg.payload;

if (raw && raw.length >= 2) {
    let weight = (raw[0] << 16) | raw[1];

    let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

    // Hardcode the Device ID for Silo 1
    let deviceId = `${gatewaySerial}-silo1`;

    msg.payload = {
        "gateway_id": gatewaySerial,
        "device_id": deviceId,
        "sensor_type": "silo_weight",
        "timestamp": new Date().toISOString(),
        "data": {
            "weight_kg": weight
        }
    };

    msg.topic = `gateway/${gatewaySerial}/silo/${deviceId}/telemetry`;
    return msg;
}
return null;

const silo = String(msg.payload ?? '').trim();

if (!['1', '2'].includes(silo)) {
    msg.payload = 'Choose Silo 1 or Silo 2.';
    return msg;
}

flow.set('ads301CalibrationSilo', silo);
msg.payload = `Selected: Silo ${silo}`;
return msg;

const kg = Number(msg.payload);

if (!Number.isFinite(kg) || kg <= 0) {
    msg.payload = 'Enter a known test weight greater than zero.';
    return msg;
}

flow.set('ads301KnownWeightKg', kg);
msg.payload = `Known test weight: ${kg} kg`;
return msg;

const silo = String(flow.get('ads301CalibrationSilo') || '');

if (!['1', '2'].includes(silo)) {
    return [null, { payload: 'Select Silo 1 or Silo 2 before setting zero.' }];
}
if (flow.get('ads301CalibrationBusy')) {
    return [null, { payload: 'A calibration sequence is already running. Wait for it to complete.' }];
}

flow.set('ads301CalibrationBusy', true);

const common = { calibrationSilo: silo, calibrationMode: 'zero' };

return [[
    {
        ...common,
        topic: `Silo ${silo}: unlock password for zero`,
        calibrationAction: `Silo ${silo}: password unlocked for zero`,
        payload: { value: 21930, fc: 6, unitid: 1, address: 49, quantity: 1 }
    },
    {
        ...common,
        topic: `Silo ${silo}: sample empty zero (LDW)`,
        calibrationAction: `Silo ${silo}: zero point sampled`,
        calibrationLast: true,
        payload: { value: [32767, 65535], fc: 16, unitid: 1, address: 16, quantity: 2 }
    }
], {
    payload: `Zero calibration queued for Silo ${silo}. Keep it empty and stable.`
}];

const silo = String(flow.get('ads301CalibrationSilo') || '');
const kg = Number(flow.get('ads301KnownWeightKg'));

// Set to 10 only when the ADS301 is configured to report 0.1 kg display increments.
const unitsPerKg = 1;
const nominal = Math.round(kg * unitsPerKg);

if (!['1', '2'].includes(silo)) {
    return [null, { payload: 'Select Silo 1 or Silo 2 before calibrating the known load.' }];
}
if (!Number.isSafeInteger(nominal) || nominal <= 0 || nominal > 8000000) {
    return [null, { payload: 'Enter a valid known test weight before calibrating.' }];
}
if (flow.get('ads301CalibrationBusy')) {
    return [null, { payload: 'A calibration sequence is already running. Wait for it to complete.' }];
}

flow.set('ads301CalibrationBusy', true);

const highWord = Math.floor(nominal / 65536);
const lowWord = nominal & 0xFFFF;
const common = { calibrationSilo: silo, calibrationMode: 'known-weight' };

return [[
    {
        ...common,
        topic: `Silo ${silo}: unlock password for known load`,
        calibrationAction: `Silo ${silo}: password unlocked for known load`,
        payload: { value: 21930, fc: 6, unitid: 1, address: 49, quantity: 1 }
    },
    {
        ...common,
        topic: `Silo ${silo}: sample known load (LWT)`,
        calibrationAction: `Silo ${silo}: known load sampled`,
        payload: { value: [32767, 65535], fc: 16, unitid: 1, address: 18, quantity: 2 }
    },
    {
        ...common,
        topic: `Silo ${silo}: unlock password for nominal value`,
        calibrationAction: `Silo ${silo}: password unlocked for nominal value`,
        payload: { value: 21930, fc: 6, unitid: 1, address: 49, quantity: 1 }
    },
    {
        ...common,
        topic: `Silo ${silo}: write nominal ${nominal} display units`,
        calibrationAction: `Silo ${silo}: nominal value ${kg} kg written`,
        payload: { value: [highWord, lowWord], fc: 16, unitid: 1, address: 20, quantity: 2 }
    },
    {
        ...common,
        topic: `Silo ${silo}: save calibration (TDD)`,
        calibrationAction: `Silo ${silo}: calibration saved`,
        calibrationLast: true,
        payload: { value: 1, fc: 6, unitid: 1, address: 48, quantity: 1 }
    }
], {
    payload: `Known-load calibration queued for Silo ${silo}: ${kg} kg. Keep the load stable until saved.`
}];

const action = msg.calibrationAction || msg.topic || 'ADS301 write';

if (msg.calibrationLast) {
    flow.set('ads301CalibrationBusy', false);
    msg.payload = `✓ ${action} — sequence complete.`;
} else {
    msg.payload = `✓ ${action}`;
}

msg.topic = 'ADS301 Calibration';
return msg;

let raw = msg.payload.data || msg.payload;

if (raw && raw.length >= 2) {
    let weight = (raw[0] << 16) | raw[1];

    let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

    // Hardcode the Device ID for Silo 1
    let deviceId = `${gatewaySerial}_silo_1`;

    msg.payload = {
        "gateway_id": gatewaySerial,
        "device_id": deviceId,
        "sensor_type": "silo_weight",
        "timestamp": new Date().toISOString(),
        "data": {
            "weight_kg": weight
        }
    };

    msg.topic = `gateway/${gatewaySerial}/silo/${deviceId}/telemetry`;
    return msg;
}
return null;

let raw = msg.payload.data || msg.payload;

if (raw && raw.length >= 2) {
    let weight = (raw[0] << 16) | raw[1];

    let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

    // Hardcode the Device ID for Silo 2
    let deviceId = `${gatewaySerial}-silo2`;

