        }
    };

    msg.topic = `gateway/${gatewaySerial}/silo/${deviceId}/telemetry`;
    return msg;
}
return null;

// ── FAI Gateway Parser (v7.3 - Always-send weight, "now" timestamp, GASCO2 workaround) ──
//
// Key fix vs v6.0: the backend does NOT want JSON in `data`. It wants the raw
// hex-encoded C-struct (sensor_telegram_t / weight array), exactly like the
// physical Tinymesh hardware sent it, with detail:"serial".
//
// Changes in v7.3 (app showed device online but no weight/graph data):
//   1. Removed the weight>0.01 guard on Packet 2 — always send the weight
//      array now, including 0g, matching confirmed old-hardware behavior.
//   2. Timestamp reverted to always-"now" (matches proven v3.1 behavior)
//      instead of preferring ChirpStack's uplink time — removes possible
//      clock-skew/query-window mismatch as a variable.
// Note: a "send a fake 0x04 keep-alive packet to flip online status" fix
// was considered and rejected — the device already shows online in the app,
// so that diagnosis didn't match the actual symptom. Not included here.
//
// Per the official sensors.h spec:
//   Type 0x01 (Env, 58 bytes): all fields Little-Endian Float32, except
//     LightALS (bytes 22-25) which is Uint32 LE.
//   Type 0x02 (Weight, 106 bytes): 50x Uint16 LE samples starting at byte 6.
//
// CONFIRMED WORKAROUND: the third-party backend's decoder reads GASCO2
// (bytes 26-29) as Uint32, not Float32 as the spec documents. We can't patch
// the backend, so this parser writes GASCO2 as a raw integer to match what
// the backend actually does, not what the spec says it should do. See the
// inline comment at that field for the verification details.

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const TARGET_CLOUD_SID = 16777216;

if (!msg.payload || !msg.payload.deviceInfo || !msg.payload.data) return null;

// ── UID: last 4 bytes of DevEUI, Big-Endian (matches dynamicUid convention) ──
const devEui = msg.payload.deviceInfo.devEui;
const uidHex = devEui.slice(-8);
const dynamicUid = parseInt(uidHex, 16);

// ── Decode the LoRa binary payload ──
// Payload is now 22 bytes (was 14, was originally 10): the Arduino sketch
// now also transmits humidity and pressure from the already-installed
// BME280 (it measures both, the code just wasn't reading them before).
// Layout, all Little-Endian:
//   bytes 0-3:   temperature (float)
//   bytes 4-5:   co2 ppm (uint16)
//   bytes 6-9:   scale weight (float)
//   bytes 10-13: light lux (float)
//   bytes 14-17: humidity %RH (float)   <-- NEW
//   bytes 18-21: pressure hPa (float)   <-- NEW
const buf = Buffer.from(msg.payload.data, 'base64');
if (buf.length < 22) return null;

const temp     = buf.readFloatLE(0);   // °C
const co2      = buf.readUInt16LE(4);  // ppm
const weight   = buf.readFloatLE(6);   // g
const lux      = buf.readFloatLE(10);  // lx
const humidity = buf.readFloatLE(14);  // %RH
const pressure = buf.readFloatLE(18);  // hPa

// ── RSSI & meta (raw integer, matching tinymesh-edge convention: Math.abs) ──
let bestRssi = -120;
if (msg.payload.rxInfo && msg.payload.rxInfo.length > 0) {
    bestRssi = Math.max(...msg.payload.rxInfo.map(rx => rx.rssi));
}
const rawRssi = Math.abs(bestRssi);
// Timestamp: match the known-working v3.1 behavior exactly. v3.1 always used
// "now" (the time Node-RED processed the packet), never the radio's own
// embedded timestamp. We previously preferred msg.payload.time (ChirpStack's
// uplink receive time) as a "more accurate" timestamp, but that's an
// unverified deviation from what's proven to work — if there's any clock
// skew between the Jetson and the app's backend, or if the app's query
// window is strict about recency, this could be why weight data silently
// fails to render in the app even though Grafana (likely more lenient on
// time range) still shows it. Reverting to "always now" removes that as a
// variable.
const timestamp = new Date().toISOString().split('.')[0] + '+00:00';

const outMessages = [];

// ==========================================
// FORGE PACKET 1: TYPE 0x01 (ENVIRONMENTAL)
// Length: 58 bytes | Signature: 013a
// Layout matches sensor_telegram_t exactly, Little-Endian floats per sensors.h spec
// ==========================================
const envBuf = Buffer.alloc(58, 0);
envBuf.writeUInt8(0x01, 0); // Byte 0: Type
envBuf.writeUInt8(0x3a, 1); // Byte 1: Length (58)

// Bytes 2-5 reserved/unused in struct — left as 0x00

envBuf.writeFloatLE(temp, 6);    // AirTemperature      (bytes 6-9)
envBuf.writeFloatLE(pressure, 10); // AirPressure (bytes 10-13) — now real BME280 hPa reading.
                                  // UNVERIFIED against backend: AirTemperature at byte 6 is
                                  // confirmed correct as Float32, but we haven't specifically
                                  // checked AirPressure. If Grafana shows nonsense here, run the
                                  // same bit-pattern check used for GASCO2.
envBuf.writeFloatLE(temp, 14);   // HumidityTemperature  (bytes 14-17)  — BME280 has one temp sensor,
                                  // reused here since there's no separate humidity-specific probe
envBuf.writeFloatLE(humidity, 18); // Humidity (bytes 18-21) — now real BME280 %RH reading.
                                  // Also unverified against backend — check Grafana after deploy.
envBuf.writeUInt32LE(Math.max(0, Math.round(lux)), 22); // LightALS (bytes 22-25) — now real VEML7700
                                            // lux data. Written as Uint32 per spec (rounded, floor
                                            // 0 since lux can't be negative). UNVERIFIED: we found
                                            // GASCO2 doesn't match its documented type, so once this
                                            // is live, check Grafana the same way — if LightALS shows
                                            // a nonsense number, the backend likely also reads this
                                            // field as a different type than Uint32 and needs the
                                            // same bit-pattern diagnosis we did for GASCO2.
envBuf.writeUInt32LE(Math.round(co2), 26); // GASCO2 (bytes 26-29) — WORKAROUND: spec sheet says
                                            // Float32 here, but the backend's fixed/third-party
                                            // decoder actually reads this field as Uint32 (same
                                            // type as LightALS next to it). Confirmed by reverse-
                                            // engineering: writing 476.0 as Float32 produced
                                            // 1139671040 in Grafana — the exact bit pattern of
                                            // that float reinterpreted as a raw uint32. Since the
                                            // backend can't be patched, we match its real behavior
                                            // instead of the documented spec: write the ppm value
                                            // directly as an integer.
envBuf.writeFloatLE(0.0, 30);    // GASTemperature       (bytes 30-33)
envBuf.writeFloatLE(0.0, 34);    // GASHumidity          (bytes 34-37)
envBuf.writeFloatLE(0.0, 38);    // GASNH3               (bytes 38-41)
envBuf.writeFloatLE(0.0, 42);    // GASCO                (bytes 42-45)
envBuf.writeFloatLE(0.0, 46);    // GASNO2               (bytes 46-49)
envBuf.writeFloatLE(temp, 50);   // BoardTemperature     (bytes 50-53)  — reuse BME280 temp
envBuf.writeFloatLE(temp, 54);   // PT100Temperature     (bytes 54-57)  — reuse BME280 temp

outMessages.push({
    topic: `gateway/${gatewaySerial}/tinymesh/out`,
    payload: {
        "_meta": { "received": timestamp },
        "block": 0,
        "data": envBuf.toString('hex'), // RAW HEX — backend decodes this itself
        "detail": "serial",             // matches the proven working contract
        "hops": 1,
        "latency": 2,
        "network_lvl": 1,
        "packet_num": Math.floor(Math.random() * 65535), // bypass cloud dedup
        "rssi": rawRssi,
        "sid": TARGET_CLOUD_SID,
        "type": "event",
        "uid": dynamicUid
    }
});

// ==========================================
// FORGE PACKET 2: TYPE 0x02 (WEIGHT ARRAY)
// Length: 106 bytes | Signature: 026a
// Array of 50x UInt16, Little-Endian (per reference decoder: "Payload stays LE")
//
// NOTE: previously guarded with `if (weight > 0.01 || weight < -0.01)` to
// skip sending when the scale read ~0g. Removed: confirmed that old hardware
// always sent weight including 0g, and the app is expected to show the scale
// dropping to zero (e.g. bird stepped off), not flatline at the last nonzero
// reading. Always transmit this packet now.
// ==========================================
{
    const wBuf = Buffer.alloc(106, 0);
    wBuf.writeUInt8(0x02, 0); // Byte 0: Type
    wBuf.writeUInt8(0x6a, 1); // Byte 1: Length (106)

    const wInt = Math.abs(Math.round(weight));

    for (let i = 0; i < 50; i++) {
        wBuf.writeUInt16LE(wInt, 6 + (i * 2));
    }

    outMessages.push({
        topic: `gateway/${gatewaySerial}/tinymesh/out`,
        payload: {
            "_meta": { "received": timestamp },
            "block": 0,
            "data": wBuf.toString('hex'), // RAW HEX, same as packet 1
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,
            "packet_num": Math.floor(Math.random() * 65535),
            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    });
}

return [ outMessages ];

// ── FAI Gateway Parser v8.0 ─────────────────────────────────────────────────
//
// Input from Arduino:
//   50-byte compact LoRaWAN batch
//   - 18 genuine weight spot readings, sampled every 10 seconds
//   - environmental spot readings taken after the weight array is full
//
// Output to backend remains unchanged:
//   Type 0x01: 58-byte environmental sensor_telegram_t
//   Type 0x02: 106-byte packet containing 50x UInt16 weight readings
//
// The backend still receives raw hex C-struct data with detail:"serial".
// No JSON sensor object is placed inside `data`.

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const TARGET_CLOUD_SID = 16777216;

const EXPECTED_PAYLOAD_LENGTH = 50;
const EXPECTED_VERSION = 1;
const MAX_WEIGHT_SAMPLES_PER_BATCH = 18;
const INVALID_WEIGHT = 0xFFFF;

// Number of recently processed batch IDs retained per device.
// This prevents a retried LoRa transmission from duplicating its 18 samples.
const RECENT_BATCH_HISTORY = 32;

if (
    !msg.payload ||
    !msg.payload.deviceInfo ||
    !msg.payload.deviceInfo.devEui ||
    !msg.payload.data
) {
    return null;
}

// ── Device identity ──────────────────────────────────────────────────────────

const devEui = String(msg.payload.deviceInfo.devEui);
const uidHex = devEui.slice(-8);
const dynamicUid = parseInt(uidHex, 16);

if (!Number.isFinite(dynamicUid)) {
    node.warn(`Unable to derive UID from DevEUI: ${devEui}`);
    return null;
}

// ── Decode the 50-byte LoRa payload ─────────────────────────────────────────

let buf;

try {
    buf = Buffer.from(msg.payload.data, "base64");
} catch (error) {
    node.warn(`Could not decode LoRa payload: ${error.message}`);
    return null;
}

if (buf.length !== EXPECTED_PAYLOAD_LENGTH) {
    node.warn(
        `Unexpected LoRa payload length from ${devEui}: ` +
        `${buf.length}; expected ${EXPECTED_PAYLOAD_LENGTH}`
    );
    return null;
}

const protocolVersion = buf.readUInt8(0);
const sampleCount = buf.readUInt8(1);
const batchNumber = buf.readUInt16LE(2);

if (protocolVersion !== EXPECTED_VERSION) {
    node.warn(
        `Unsupported payload version from ${devEui}: ` +
        `${protocolVersion}`
    );
    return null;
}

if (
    sampleCount === 0 ||
    sampleCount > MAX_WEIGHT_SAMPLES_PER_BATCH
) {
    node.warn(
        `Invalid sample count from ${devEui}: ${sampleCount}`
    );
    return null;
}

if (sampleCount !== MAX_WEIGHT_SAMPLES_PER_BATCH) {
    node.warn(
        `Partial weight batch from ${devEui}: ` +
        `${sampleCount}/${MAX_WEIGHT_SAMPLES_PER_BATCH} samples`
    );
}

// Environmental values are scaled integers in the LoRa packet.
const temp = buf.readInt16LE(40) / 100.0;
const co2 = buf.readUInt16LE(42);
const lux = buf.readUInt16LE(44);
const humidity = buf.readUInt16LE(46) / 100.0;
const pressure = buf.readUInt16LE(48) / 10.0;

// ── Retrieve persistent per-device parser state ─────────────────────────────
//
// State is separated by DevEUI so several LoRa nodes can use the same parser.

let parserState = context.get("faiBatchParserState");

if (
    !parserState ||
    typeof parserState !== "object" ||
    Array.isArray(parserState)
) {
    parserState = {};
}

let deviceState = parserState[devEui];

if (
    !deviceState ||
    typeof deviceState !== "object" ||
    Array.isArray(deviceState)
) {
    deviceState = {
        weightQueue: [],
        recentBatchNumbers: []
    };
}

if (!Array.isArray(deviceState.weightQueue)) {
    deviceState.weightQueue = [];
}

if (!Array.isArray(deviceState.recentBatchNumbers)) {
    deviceState.recentBatchNumbers = [];
}

// ── Reject duplicate LoRa batches ───────────────────────────────────────────
//
// This matters because the Arduino retains and retries a completed batch if it
// does not receive +EVT:TX_DONE. The network may occasionally receive both
// attempts even though the Arduino believed the first attempt failed.

if (deviceState.recentBatchNumbers.includes(batchNumber)) {
    node.warn(
        `Ignoring duplicate batch ${batchNumber} from ${devEui}`
    );
    return null;
}

deviceState.recentBatchNumbers.push(batchNumber);

if (
    deviceState.recentBatchNumbers.length >
    RECENT_BATCH_HISTORY
) {
    deviceState.recentBatchNumbers =
        deviceState.recentBatchNumbers.slice(
            -RECENT_BATCH_HISTORY
        );
}

// ── Add genuine weight readings to the device queue ─────────────────────────

let invalidWeightCount = 0;

for (let i = 0; i < sampleCount; i++) {
    const weight = buf.readUInt16LE(4 + (i * 2));

    if (weight === INVALID_WEIGHT) {
        invalidWeightCount++;
        continue;
    }

    // Zero is a genuine measurement and must be retained.
    deviceState.weightQueue.push(weight);
}

if (invalidWeightCount > 0) {
    node.warn(
        `Batch ${batchNumber} from ${devEui} contained ` +
        `${invalidWeightCount} invalid scale reading(s)`
    );
}

// ── RSSI and timestamp ───────────────────────────────────────────────────────

let bestRssi = -120;

if (
    Array.isArray(msg.payload.rxInfo) &&
    msg.payload.rxInfo.length > 0
) {
    const validRssiValues = msg.payload.rxInfo
        .map(rx => Number(rx.rssi))
        .filter(value => Number.isFinite(value));

    if (validRssiValues.length > 0) {
        bestRssi = Math.max(...validRssiValues);
    }
}

const rawRssi = Math.abs(bestRssi);

// Preserve the proven v3.1/v7.3 behaviour: timestamp is the time at which
// Node-RED processes the received LoRa packet.
const timestamp =
    new Date().toISOString().split(".")[0] + "+00:00";

const outMessages = [];

function makeBackendMessage(hexData) {
    return {
        topic: `gateway/${gatewaySerial}/tinymesh/out`,
        payload: {
            "_meta": {
                "received": timestamp
            },
            "block": 0,
            "data": hexData,
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,

            // Continue varying this value to avoid the cloud treating two
            // otherwise similar packets as duplicates.
            "packet_num": Math.floor(Math.random() * 65535),

            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    };
}

// ============================================================================
// FORGE PACKET 1: TYPE 0x01 — ENVIRONMENTAL
// Length: 58 bytes
// Signature: 013a
// ============================================================================

const envBuf = Buffer.alloc(58, 0);

envBuf.writeUInt8(0x01, 0);
envBuf.writeUInt8(0x3A, 1);

// Bytes 2–5 remain reserved and zero-filled.

envBuf.writeFloatLE(temp, 6);          // AirTemperature
envBuf.writeFloatLE(pressure, 10);     // AirPressure
envBuf.writeFloatLE(temp, 14);         // HumidityTemperature
envBuf.writeFloatLE(humidity, 18);     // Humidity

envBuf.writeUInt32LE(
    Math.min(
        0xFFFFFFFF,
        Math.max(0, Math.round(lux))
    ),
    22
);                                    // LightALS

// Backend workaround: its decoder reads GASCO2 as UInt32 rather than Float32.
envBuf.writeUInt32LE(
    Math.min(
        0xFFFFFFFF,
        Math.max(0, Math.round(co2))
    ),
    26
);                                    // GASCO2

envBuf.writeFloatLE(0.0, 30);          // GASTemperature
envBuf.writeFloatLE(0.0, 34);          // GASHumidity
envBuf.writeFloatLE(0.0, 38);          // GASNH3
envBuf.writeFloatLE(0.0, 42);          // GASCO
envBuf.writeFloatLE(0.0, 46);          // GASNO2
envBuf.writeFloatLE(temp, 50);         // BoardTemperature
envBuf.writeFloatLE(temp, 54);         // PT100Temperature

outMessages.push(
    makeBackendMessage(envBuf.toString("hex"))
);

node.warn(
    `WEIGHT QUEUE — device=${devEui}, batch=${batchNumber}, ` +
    `added=${sampleCount}, invalid=${invalidWeightCount}, ` +
    `queue=${deviceState.weightQueue.length}/50`
);
// ============================================================================
// FORGE PACKET 2: TYPE 0x02 — 50-SAMPLE WEIGHT ARRAY
// Length: 106 bytes
// Signature: 026a
// ============================================================================
//
// One LoRa packet contributes 18 weight readings. The queue is retained across
// invocations. A backend packet is produced only when 50 genuine samples are
// available.
//
// 50 samples × 10 seconds = 500 seconds = 8 minutes 20 seconds of measurements.

while (deviceState.weightQueue.length >= 50) {
    const weightSamples =
        deviceState.weightQueue.splice(0, 50);

    const wBuf = Buffer.alloc(106, 0);

    wBuf.writeUInt8(0x02, 0);
    wBuf.writeUInt8(0x6A, 1);

    // Bytes 2–5 remain reserved and zero-filled.

    for (let i = 0; i < 50; i++) {
        const weight = Math.min(
            65535,
            Math.max(
                0,
                Math.round(weightSamples[i])
            )
        );

        wBuf.writeUInt16LE(
            weight,
            6 + (i * 2)
        );
    }

    outMessages.push(
        makeBackendMessage(wBuf.toString("hex"))
    );
}

// ── Save the remaining queue and duplicate history ──────────────────────────

parserState[devEui] = deviceState;
context.set("faiBatchParserState", parserState);

// A one-output Node-RED Function node expects an array containing the list of
// messages that should be emitted from that output.
return [outMessages];

// ── FAI Gateway Parser v8.2 ─────────────────────────────────────────────────
//
// Arduino LoRaWAN input:
//   50-byte compact payload containing:
//     - 18 weight spot readings sampled at 10-second intervals
//     - One environmental spot reading after the 18th weight reading
//
// Backend output remains unchanged:
//   Type 0x01: 58-byte environmental packet, signature 013a
//   Type 0x02: 106-byte weight packet, signature 026a
//
// Weight handling:
//   - Genuine 0 g readings are retained.
//   - Invalid Arduino readings are encoded as 0xFFFF.
//   - Invalid readings are stored internally as null.
//   - Every null still occupies one 10-second time slot.
//   - When producing the fixed UInt16[50] backend array, null values are
//     replaced using last-observation-carried-forward.
//   - If there has never been a valid reading, the fallback value is 0.
//
// Diagnostics:
//   - Logs queue length after every LoRa batch.
//   - Logs when a 106-byte weight packet is created.
//   - Logs the number and type of emitted backend messages.
//
// IMPORTANT:
//   Configure filesystem-backed Node-RED context storage if pending samples
//   must survive a Node-RED or Jetson restart.

// ============================================================================
// Configuration
// ============================================================================

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

const TARGET_CLOUD_SID = 16777216;

const EXPECTED_PAYLOAD_LENGTH = 50;
const EXPECTED_VERSION = 1;
const MAX_WEIGHT_SAMPLES_PER_BATCH = 18;
const INVALID_WEIGHT = 0xFFFF;

const REQUIRED_BACKEND_WEIGHT_SAMPLES = 50;

// Number of recently processed compact payload signatures retained per device.
const RECENT_BATCH_HISTORY = 32;

// ============================================================================
// Validate incoming ChirpStack message
// ============================================================================

if (
    !msg.payload ||
    !msg.payload.deviceInfo ||
    !msg.payload.deviceInfo.devEui ||
    msg.payload.data === undefined ||
    msg.payload.data === null
) {
    node.warn("Invalid ChirpStack message: required fields are missing");
    return null;
}

// ============================================================================
// Device identity
// ============================================================================

const devEui =
    String(msg.payload.deviceInfo.devEui).toUpperCase();

const uidHex = devEui.slice(-8);

if (!/^[0-9A-F]{8}$/.test(uidHex)) {
    node.warn(`Invalid DevEUI received: ${devEui}`);
    return null;
}

const dynamicUid = parseInt(uidHex, 16);

if (!Number.isFinite(dynamicUid)) {
    node.warn(`Could not calculate UID from DevEUI: ${devEui}`);
    return null;
}

// ============================================================================
// Decode the Arduino's 50-byte compact LoRa payload
// ============================================================================

let buf;

try {
    if (Buffer.isBuffer(msg.payload.data)) {
        buf = msg.payload.data;
    } else {
        buf = Buffer.from(
            String(msg.payload.data),
            "base64"
        );
    }
} catch (error) {
    node.warn(
        `Could not decode LoRa payload from ${devEui}: ` +
        error.message
    );

    return null;
}

if (buf.length !== EXPECTED_PAYLOAD_LENGTH) {
    node.warn(
        `Unexpected payload length from ${devEui}: ` +
        `${buf.length} bytes; expected ${EXPECTED_PAYLOAD_LENGTH}`
    );

    return null;
}

// Arduino payload layout:
//
//   Byte 0:       protocol version
//   Byte 1:       number of weight samples
//   Bytes 2-3:    batch number, UInt16 LE
//   Bytes 4-39:   18 × weight samples, UInt16 LE
//   Bytes 40-41:  temperature × 100, Int16 LE
//   Bytes 42-43:  CO2 ppm, UInt16 LE
//   Bytes 44-45:  light lux, UInt16 LE
//   Bytes 46-47:  humidity × 100, UInt16 LE
//   Bytes 48-49:  pressure × 10, UInt16 LE

const protocolVersion = buf.readUInt8(0);
const sampleCount = buf.readUInt8(1);
const batchNumber = buf.readUInt16LE(2);

if (protocolVersion !== EXPECTED_VERSION) {
    node.warn(
        `Unsupported payload version from ${devEui}: ` +
        `${protocolVersion}; expected ${EXPECTED_VERSION}`
    );

    return null;
}

if (
    sampleCount === 0 ||
    sampleCount > MAX_WEIGHT_SAMPLES_PER_BATCH
) {
    node.warn(
        `Invalid weight sample count from ${devEui}: ` +
        sampleCount
    );

    return null;
}

if (sampleCount !== MAX_WEIGHT_SAMPLES_PER_BATCH) {
    node.warn(
        `Partial weight batch from ${devEui}: ` +
        `${sampleCount}/${MAX_WEIGHT_SAMPLES_PER_BATCH}`
    );
}

// Environmental values are scaled integers in the compact LoRa packet.
const temp = buf.readInt16LE(40) / 100.0;
const co2 = buf.readUInt16LE(42);
const lux = buf.readUInt16LE(44);
const humidity = buf.readUInt16LE(46) / 100.0;
const pressure = buf.readUInt16LE(48) / 10.0;

// ============================================================================
// Retrieve per-device parser state
// ============================================================================

let parserState =
    context.get("faiBatchParserState");

if (
    !parserState ||
    typeof parserState !== "object" ||
    Array.isArray(parserState)
) {
    parserState = {};
}

let deviceState =
    parserState[devEui];

if (
    !deviceState ||
    typeof deviceState !== "object" ||
    Array.isArray(deviceState)
) {
    deviceState = {
        weightQueue: [],
        recentBatchSignatures: [],
        outputLastValidWeight: null
    };
}

if (!Array.isArray(deviceState.weightQueue)) {
    deviceState.weightQueue = [];
}

if (!Array.isArray(deviceState.recentBatchSignatures)) {
    deviceState.recentBatchSignatures = [];
}

if (!Number.isFinite(deviceState.outputLastValidWeight)) {
    deviceState.outputLastValidWeight = null;
}

// ============================================================================
// Duplicate batch protection
// ============================================================================
//
// The Arduino retains a batch until the radio reports TX_DONE. In unusual
// circumstances, the network could receive a retransmitted copy.
//
// The signature includes the batch number and complete payload, rather than
// batch number alone, because the Arduino batch counter restarts after reboot.

const batchSignature =
    `${batchNumber}:${buf.toString("hex")}`;

if (
    deviceState.recentBatchSignatures.includes(
        batchSignature
    )
) {
    node.warn(
        `Ignoring duplicate batch ${batchNumber} from ${devEui}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `duplicate batch ${batchNumber}`
    });

    return null;
}

deviceState.recentBatchSignatures.push(
    batchSignature
);

if (
    deviceState.recentBatchSignatures.length >
    RECENT_BATCH_HISTORY
) {
    deviceState.recentBatchSignatures =
        deviceState.recentBatchSignatures.slice(
            -RECENT_BATCH_HISTORY
        );
}

// ============================================================================
// Add all received weight time slots to the queue
// ============================================================================
//
// Invalid readings are added as null. They are not discarded.
//
// This means every queue position still represents one 10-second sample slot.

let invalidWeightCount = 0;
let validWeightCount = 0;

for (let i = 0; i < sampleCount; i++) {
    const weight =
        buf.readUInt16LE(4 + (i * 2));

    if (weight === INVALID_WEIGHT) {
        invalidWeightCount++;

        // Preserve the failed 10-second time slot.
        deviceState.weightQueue.push(null);
    } else {
        validWeightCount++;

        // Includes genuine zero-weight readings.
        deviceState.weightQueue.push(weight);
    }
}

if (invalidWeightCount > 0) {
    node.warn(
        `Batch ${batchNumber} from ${devEui} contained ` +
        `${invalidWeightCount} invalid scale reading(s)`
    );
}

node.warn(
    `WEIGHT QUEUE — device=${devEui}, ` +
    `batch=${batchNumber}, ` +
    `added=${sampleCount}, ` +
    `valid=${validWeightCount}, ` +
    `invalid=${invalidWeightCount}, ` +
    `queue=${deviceState.weightQueue.length}/` +
    `${REQUIRED_BACKEND_WEIGHT_SAMPLES}`
);

// ============================================================================
// RSSI
// ============================================================================

let bestRssi = -120;

if (
    Array.isArray(msg.payload.rxInfo) &&
    msg.payload.rxInfo.length > 0
) {
    const validRssiValues =
        msg.payload.rxInfo
            .map(rx => Number(rx.rssi))
            .filter(value => Number.isFinite(value));

    if (validRssiValues.length > 0) {
        bestRssi = Math.max(...validRssiValues);
    }
}

const rawRssi = Math.abs(bestRssi);

// ============================================================================
// Backend timestamp
// ============================================================================
//
// Preserve the known-working v3.1/v7.3 behaviour: use the time at which
// Node-RED processes the packet.

const timestamp =
    new Date().toISOString().split(".")[0] +
    "+00:00";

// ============================================================================
// Backend message helper
// ============================================================================

const outMessages = [];

function makeBackendMessage(hexData) {
    return {
        topic:
            `gateway/${gatewaySerial}/tinymesh/out`,

        payload: {
            "_meta": {
                "received": timestamp
            },

            "block": 0,
            "data": hexData,
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,

            // Vary this to reduce the chance of backend deduplication.
            "packet_num":
                Math.floor(Math.random() * 65535),

            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    };
