// FORGE PACKET 1: TYPE 0x01 — ENVIRONMENTAL
//
// Backend length: 58 bytes
// Signature:      013a
// ============================================================================

const envBuf = Buffer.alloc(58, 0);

envBuf.writeUInt8(0x01, 0);
envBuf.writeUInt8(0x3A, 1);

// Bytes 2-5 remain reserved and zero-filled.

envBuf.writeFloatLE(
    temp,
    6
);                                      // AirTemperature

envBuf.writeFloatLE(
    pressure,
    10
);                                      // AirPressure

envBuf.writeFloatLE(
    temp,
    14
);                                      // HumidityTemperature

envBuf.writeFloatLE(
    humidity,
    18
);                                      // Humidity

envBuf.writeUInt32LE(
    Math.min(
        0xFFFFFFFF,
        Math.max(0, Math.round(lux))
    ),
    22
);                                      // LightALS

