//                   = 8 minutes 20 seconds
//
// One or more weight packets are generated whenever enough queued time slots
// are available.
// ============================================================================

let generatedWeightPacketCount = 0;

while (
    deviceState.weightQueue.length >=
    REQUIRED_BACKEND_WEIGHT_SAMPLES
) {
    node.warn(
        `CREATING WEIGHT PACKET — ` +
        `device=${devEui}, ` +
        `queueBefore=${deviceState.weightQueue.length}`
    );

    const queuedSamples =
        deviceState.weightQueue.splice(
            0,
            REQUIRED_BACKEND_WEIGHT_SAMPLES
        );

    const wBuf = Buffer.alloc(106, 0);

    wBuf.writeUInt8(0x02, 0);
    wBuf.writeUInt8(0x6A, 1);

    // Bytes 2-5 remain reserved and zero-filled.

    let carryWeight =
        Number.isFinite(
            deviceState.outputLastValidWeight
        )
            ? deviceState.outputLastValidWeight
            : null;

    let substitutedCount = 0;
    let leadingZeroFallbackCount = 0;
    let genuineZeroCount = 0;

    for (
        let i = 0;
        i < REQUIRED_BACKEND_WEIGHT_SAMPLES;
        i++
    ) {
        const queuedValue =
            queuedSamples[i];

        let outputWeight;

        if (queuedValue === null) {
            substitutedCount++;

            if (carryWeight !== null) {
                // Last-observation-carried-forward.
                outputWeight = carryWeight;
            } else {
                // No earlier valid weight exists.
                outputWeight = 0;
                leadingZeroFallbackCount++;
            }
        } else {
            outputWeight = queuedValue;
            carryWeight = queuedValue;

            if (queuedValue === 0) {
                genuineZeroCount++;
            }
        }

        outputWeight = Math.min(
            65534,
            Math.max(
                0,
                Math.round(outputWeight)
            )
        );

        wBuf.writeUInt16LE(
            outputWeight,
            6 + (i * 2)
        );
    }

    // Carry the latest genuine measurement into the next output packet.
    deviceState.outputLastValidWeight =
        carryWeight;

    const weightHex =
        wBuf.toString("hex");

    node.warn(
        `WEIGHT PACKET CREATED — ` +
        `device=${devEui}, ` +
        `bytes=${wBuf.length}, ` +
        `hexChars=${weightHex.length}, ` +
        `signature=${weightHex.slice(0, 4)}, ` +
        `firstWeight=${wBuf.readUInt16LE(6)}, ` +
        `lastWeight=${wBuf.readUInt16LE(104)}, ` +
        `substituted=${substitutedCount}, ` +
        `leadingZeroFallbacks=${leadingZeroFallbackCount}, ` +
        `genuineZeros=${genuineZeroCount}, ` +
        `queueRemaining=${deviceState.weightQueue.length}`
    );

    outMessages.push(
        makeBackendMessage(weightHex)
    );

    generatedWeightPacketCount++;
}

// ============================================================================
// Save parser state before emitting messages
// ============================================================================

parserState[devEui] = deviceState;

context.set(
    "faiBatchParserState",
    parserState
);

// ============================================================================
// Final diagnostics
// ============================================================================

const outputSignatures =
    outMessages.map(message =>
        String(message.payload.data).slice(0, 4)
    );

node.warn(
    `PARSER OUTPUT — ` +
    `device=${devEui}, ` +
    `messages=${outMessages.length}, ` +
    `signatures=${outputSignatures.join(",")}, ` +
    `weightPackets=${generatedWeightPacketCount}, ` +
    `queueRemaining=${deviceState.weightQueue.length}`
);

if (generatedWeightPacketCount > 0) {
    node.status({
        fill: "green",
        shape: "dot",
        text:
            `${outMessages.length} outputs; ` +
            `${deviceState.weightQueue.length} queued`
    });
} else {
    node.status({
        fill: "blue",
        shape: "ring",
        text:
            `${deviceState.weightQueue.length}/50 weights`
    });
}

// ============================================================================
// Explicitly send all generated messages through output 1
// ============================================================================
//
// On most uplinks this sends one environmental message.
//
// When 50 weight time slots are available, it sends:
//   1. Environmental packet beginning 013a
//   2. Weight packet beginning 026a

node.send([outMessages]);

return null;

