            "hops": 1,
            "latency": 2,
            "network_lvl": 1,

            "packet_num":
                Math.floor(Math.random() * 65535),

            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    };
