if (
    sampleCount === 0 ||
    sampleCount > WEIGHTS_PER_LORA_BATCH
) {
    node.warn(
        `Invalid weight sample count from ${devEui}: ` +
        sampleCount
    );

    return null;
}

if (sampleCount !== WEIGHTS_PER_LORA_BATCH) {
    node.warn(
        `Partial LoRa weight batch from ${devEui}: ` +
        `${sampleCount}/${WEIGHTS_PER_LORA_BATCH}`
    );
}

// ============================================================================
// Decode environmental fields
// ============================================================================

const temp =
    buf.readInt16LE(40) / 100.0;

const co2 =
    buf.readUInt16LE(42);

const lux =
    buf.readUInt16LE(44);

const humidity =
    buf.readUInt16LE(46) / 100.0;

const pressure =
    buf.readUInt16LE(48) / 10.0;

// ============================================================================
// Load GLOBAL per-device state
// ============================================================================

let weightQueue =
    global.get(queueKey);

if (!Array.isArray(weightQueue)) {
    weightQueue = [];
}

let recentBatchSignatures =
    global.get(signaturesKey);

if (!Array.isArray(recentBatchSignatures)) {
    recentBatchSignatures = [];
}

let outputLastValidWeight =
    global.get(carryWeightKey);

if (!Number.isFinite(outputLastValidWeight)) {
    outputLastValidWeight = null;
}

node.warn(
    `GLOBAL STATE LOADED — ` +
    `device=${devEui}, ` +
    `batch=${batchNumber}, ` +
    `queueBefore=${weightQueue.length}`
);

// ============================================================================
// Duplicate protection
// ============================================================================
//
// The Arduino retains a packet until the RAK radio reports TX_DONE.
// In unusual circumstances, the same LoRa payload may therefore arrive twice.
//
// Batch number alone is not sufficient because it restarts after an Arduino
// reboot. The complete payload is included in the signature.

const batchSignature =
    `${batchNumber}:${buf.toString("hex")}`;

if (
    recentBatchSignatures.includes(batchSignature)
) {
    node.warn(
        `Ignoring duplicate batch ${batchNumber} from ${devEui}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `duplicate batch ${batchNumber}`
    });

    return null;
}

recentBatchSignatures.push(batchSignature);

if (
    recentBatchSignatures.length >
    RECENT_BATCH_HISTORY
) {
    recentBatchSignatures =
        recentBatchSignatures.slice(
            -RECENT_BATCH_HISTORY
        );
}

// ============================================================================
// Add all weight time slots to the global queue
// ============================================================================
//
// Every array position represents one 10-second interval.
//
// Invalid readings are added as null rather than being discarded, so the
// time grid is not compressed.

let validWeightCount = 0;
let invalidWeightCount = 0;

for (let i = 0; i < sampleCount; i++) {
    const weight =
        buf.readUInt16LE(4 + (i * 2));

    if (weight === INVALID_WEIGHT) {
        invalidWeightCount++;

        weightQueue.push(null);
    } else {
        validWeightCount++;

        // Includes genuine zero-weight readings.
        weightQueue.push(weight);
    }
}

if (invalidWeightCount > 0) {
    node.warn(
        `Batch ${batchNumber} from ${devEui} contained ` +
        `${invalidWeightCount} invalid scale reading(s)`
    );
}

node.warn(
    `WEIGHT QUEUE — ` +
    `device=${devEui}, ` +
    `batch=${batchNumber}, ` +
    `added=${sampleCount}, ` +
    `valid=${validWeightCount}, ` +
    `invalid=${invalidWeightCount}, ` +
    `queue=${weightQueue.length}/${WEIGHTS_PER_BACKEND_PACKET}`
);

// ============================================================================
// RSSI
// ============================================================================

let bestRssi = -120;

if (
    Array.isArray(msg.payload.rxInfo) &&
    msg.payload.rxInfo.length > 0
) {
    const validRssiValues =
        msg.payload.rxInfo
            .map(rx => Number(rx.rssi))
            .filter(value => Number.isFinite(value));

    if (validRssiValues.length > 0) {
        bestRssi =
            Math.max(...validRssiValues);
    }
}

const rawRssi =
    Math.abs(bestRssi);

// ============================================================================
// Backend timestamp
// ============================================================================
//
// Preserve the known-working behaviour: use the time at which Node-RED
// processes the received LoRaWAN message.

const timestamp =
    new Date().toISOString().split(".")[0] +
    "+00:00";

// ============================================================================
// Backend message helper
// ============================================================================

const outMessages = [];

function makeBackendMessage(hexData) {
    return {
        topic:
            `gateway/${gatewaySerial}/tinymesh/out`,

        payload: {
            "_meta": {
                "received": timestamp
            },

            "block": 0,
            "data": hexData,
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,

            "packet_num":
                Math.floor(Math.random() * 65535),

            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    };
}

// ============================================================================
// Forge Packet 1: environmental
//
// Type:      0x01
// Length:    58 bytes
// Signature: 013a
// ============================================================================

const envBuf =
    Buffer.alloc(58, 0);

envBuf.writeUInt8(0x01, 0);
envBuf.writeUInt8(0x3A, 1);

// Bytes 2-5 remain reserved and zero-filled.

envBuf.writeFloatLE(
    temp,
    6
);                                      // AirTemperature

envBuf.writeFloatLE(
    pressure,
    10
);                                      // AirPressure

envBuf.writeFloatLE(
    temp,
    14
);                                      // HumidityTemperature

envBuf.writeFloatLE(
    humidity,
    18
);                                      // Humidity

envBuf.writeUInt32LE(
    Math.min(
        0xFFFFFFFF,
        Math.max(
            0,
            Math.round(lux)
        )
    ),
    22
);                                      // LightALS

// Confirmed backend workaround:
// GASCO2 must be written as UInt32, not Float32.
envBuf.writeUInt32LE(
    Math.min(
        0xFFFFFFFF,
        Math.max(
            0,
            Math.round(co2)
        )
    ),
    26
);                                      // GASCO2

envBuf.writeFloatLE(0.0, 30);            // GASTemperature
envBuf.writeFloatLE(0.0, 34);            // GASHumidity
envBuf.writeFloatLE(0.0, 38);            // GASNH3
envBuf.writeFloatLE(0.0, 42);            // GASCO
envBuf.writeFloatLE(0.0, 46);            // GASNO2
envBuf.writeFloatLE(temp, 50);           // BoardTemperature
envBuf.writeFloatLE(temp, 54);           // PT100Temperature

const environmentHex =
    envBuf.toString("hex");

outMessages.push(
    makeBackendMessage(environmentHex)
);

// ============================================================================
// Forge Packet 2: 50-sample weight array
//
// Type:      0x02
// Length:    106 bytes
// Signature: 026a
//
// Fifty values represent:
//   50 × 10 seconds = 500 seconds = 8 minutes 20 seconds
// ============================================================================

let generatedWeightPacketCount = 0;

while (
    weightQueue.length >=
    WEIGHTS_PER_BACKEND_PACKET
) {
    node.warn(
        `CREATING WEIGHT PACKET — ` +
        `device=${devEui}, ` +
        `queueBefore=${weightQueue.length}`
    );

    const queuedSamples =
        weightQueue.splice(
            0,
            WEIGHTS_PER_BACKEND_PACKET
        );

    const wBuf =
        Buffer.alloc(106, 0);

    wBuf.writeUInt8(0x02, 0);
    wBuf.writeUInt8(0x6A, 1);

    // Bytes 2-5 remain reserved and zero-filled.

    let carryWeight =
        Number.isFinite(outputLastValidWeight)
            ? outputLastValidWeight
            : null;

    let substitutedCount = 0;
    let leadingZeroFallbackCount = 0;
    let genuineZeroCount = 0;

    for (
        let i = 0;
        i < WEIGHTS_PER_BACKEND_PACKET;
        i++
    ) {
        const queuedValue =
            queuedSamples[i];

        let outputWeight;

        if (queuedValue === null) {
            substitutedCount++;

            if (carryWeight !== null) {
                // Last valid observation carried forward.
                outputWeight = carryWeight;
            } else {
                // No genuine earlier reading is available.
                outputWeight = 0;
                leadingZeroFallbackCount++;
            }
        } else {
            outputWeight = queuedValue;
            carryWeight = queuedValue;

            if (queuedValue === 0) {
                genuineZeroCount++;
            }
        }

        outputWeight =
            Math.min(
                65534,
                Math.max(
                    0,
                    Math.round(outputWeight)
                )
            );

        wBuf.writeUInt16LE(
            outputWeight,
            6 + (i * 2)
        );
    }

    outputLastValidWeight =
        carryWeight;

    const weightHex =
        wBuf.toString("hex");

    node.warn(
        `WEIGHT PACKET CREATED — ` +
        `device=${devEui}, ` +
        `bytes=${wBuf.length}, ` +
        `hexChars=${weightHex.length}, ` +
        `signature=${weightHex.slice(0, 4)}, ` +
        `firstWeight=${wBuf.readUInt16LE(6)}, ` +
        `lastWeight=${wBuf.readUInt16LE(104)}, ` +
        `substituted=${substitutedCount}, ` +
        `leadingZeroFallbacks=${leadingZeroFallbackCount}, ` +
        `genuineZeros=${genuineZeroCount}, ` +
        `queueRemaining=${weightQueue.length}`
    );

    outMessages.push(
        makeBackendMessage(weightHex)
    );

    generatedWeightPacketCount++;
}

// ============================================================================
// Save per-device state to GLOBAL context
// ============================================================================

global.set(
    queueKey,
    weightQueue
);

global.set(
    signaturesKey,
    recentBatchSignatures
);

global.set(
    carryWeightKey,
    outputLastValidWeight
);

// Read state back immediately to verify that the write succeeded.
const savedQueue =
    global.get(queueKey);

const savedSignatures =
    global.get(signaturesKey);

const savedCarryWeight =
    global.get(carryWeightKey);

const savedQueueLength =
    Array.isArray(savedQueue)
        ? savedQueue.length
        : -1;

const savedSignatureCount =
    Array.isArray(savedSignatures)
        ? savedSignatures.length
        : -1;

node.warn(
    `GLOBAL STATE SAVED — ` +
    `device=${devEui}, ` +
    `queueSaved=${savedQueueLength}, ` +
    `signaturesSaved=${savedSignatureCount}, ` +
    `carryWeight=${Number.isFinite(savedCarryWeight) ? savedCarryWeight : "none"}`
);

// ============================================================================
// Output diagnostics
// ============================================================================

const outputSignatures =
    outMessages.map(
        outputMessage =>
            String(
                outputMessage.payload.data
            ).slice(0, 4)
    );

node.warn(
    `PARSER OUTPUT — ` +
    `device=${devEui}, ` +
    `messages=${outMessages.length}, ` +
    `signatures=${outputSignatures.join(",")}, ` +
    `weightPackets=${generatedWeightPacketCount}, ` +
    `queueRemaining=${weightQueue.length}`
);

if (generatedWeightPacketCount > 0) {
    node.status({
        fill: "green",
        shape: "dot",
        text:
            `${generatedWeightPacketCount} weight packet; ` +
            `${weightQueue.length} queued`
    });
} else {
    node.status({
        fill: "blue",
        shape: "ring",
        text:
            `${weightQueue.length}/50 weights`
    });
}

// ============================================================================
// Send every generated message through output 1
// ============================================================================
//
// Normally:
//   one 013a environmental message.
//
// When 50 weight slots are available:
//   one 013a environmental message;
//   one 026a weight message.

node.send([outMessages]);

return null;
